function ensureAudio(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}catch{return null}}
function sfx(type){if(!audioOn)return;const ctx=ensureAudio();if(!ctx)return;try{const notes=type==='dice'?[260,390]:type==='cash'?[560,740]:type==='event'?[310,465,620]:[380];notes.forEach((hz,i)=>{const o=ctx.createOscillator(),v=ctx.createGain();o.connect(v);v.connect(ctx.destination);o.type=type==='event'?'sine':'triangle';o.frequency.value=hz;const start=ctx.currentTime+i*.055;v.gain.setValueAtTime(.045,start);v.gain.exponentialRampToValueAtTime(.001,start+.2);o.start(start);o.stop(start+.21)})}catch{}}
function musicStart(){const ctx=ensureAudio();if(!ctx||musicTimer)return;const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];musicTimer=setInterval(()=>{if(!musicOn)return;const o=ctx.createOscillator(),v=ctx.createGain();o.type='sine';o.frequency.value=notes[musicStep++%notes.length];o.connect(v);v.connect(ctx.destination);const t=ctx.currentTime;v.gain.setValueAtTime(.0001,t);v.gain.exponentialRampToValueAtTime(.012,t+.08);v.gain.exponentialRampToValueAtTime(.0001,t+1.15);o.start(t);o.stop(t+1.2)},1250)}
