async function api(path,options={}){const response=await fetch(path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}});const data=await response.json();if(!response.ok)throw new Error(data.error||`Server error ${response.status}`);return data}
function normalizeOnlineState(state,players=onlineSession.players){g=state;g.players.forEach((p,i)=>{p.name=players[i]||p.name;p.human=i===onlineSession.index;p.taxPaid??=0;p.taxHistory??=[];p.quarterStartCash??=p.cash;p.quarterCapex??=0});latestRoomUpdate=Date.now();$('#welcome').classList.add('hidden');$('#game').classList.remove('hidden');render();addLog('SYSTEM',`Connected to online room ${onlineSession.code} as ${g.players[onlineSession.index].name}.`)}
async function publishRoomState(){if(!onlineSession||!g)return;try{const result=await api(`/api/rooms/${onlineSession.code}`,{method:'PUT',body:JSON.stringify({state:g})});latestRoomUpdate=result.updatedAt;$('#connection-status').textContent=`· ROOM ${onlineSession.code} · SYNCED`}catch(error){$('#connection-status').textContent=`· OFFLINE`;toast(`Room sync failed: ${error.message}`)}}
function startRoomPolling(){clearInterval(roomPoll);roomPoll=setInterval(async()=>{if(!onlineSession)return;try{const room=await api(`/api/rooms/${onlineSession.code}`);onlineSession.players=room.players;if(!g&&room.state){normalizeOnlineState(room.state,room.players);return}if(!g)return;let namesChanged=false;room.players.forEach((name,i)=>{if(g.players[i]&&g.players[i].name!==name){g.players[i].name=name;namesChanged=true}});if(namesChanged)render();if(room.state&&room.updatedAt>latestRoomUpdate&&room.state.turn===onlineSession.index){normalizeOnlineState(room.state,room.players)}$('#connection-status').textContent=`· ROOM ${onlineSession.code} · ONLINE`}catch{$('#connection-status').textContent='· RECONNECTING'}} ,1400)}
async function createRoom(){try{const data=await api('/api/rooms',{method:'POST',body:JSON.stringify({name:$('#player-name').value.trim()||'Treasurer'})});onlineSession={code:data.code,index:0,name:data.players[0],players:data.players};mode='online';$('#room-help').textContent=`Room ${data.code} created. Share this code; your opponent can join while you play.`;$('#room-code').value=data.code;start()}catch(error){toast(error.message)}}
async function joinRoom(){const code=$('#room-code').value.trim().toUpperCase();if(!code){toast('Enter a room code first.');return}try{const data=await api(`/api/rooms/${code}/join`,{method:'POST',body:JSON.stringify({name:$('#player-name').value.trim()||'Guest'})});onlineSession={code:data.code,index:1,name:data.players[1],players:data.players};$('#room-help').textContent=`Joined ${data.code}. Waiting for the room host to open the game…`;$('#join-room').disabled=true;const wait=async()=>{try{const room=await api(`/api/rooms/${code}`);onlineSession.players=room.players;if(room.state){normalizeOnlineState(room.state,room.players);startRoomPolling();return}setTimeout(wait,1000)}catch(error){$('#room-help').textContent=error.message;$('#join-room').disabled=false}};wait()}catch(error){toast(error.message)}}

