function settleQuarter(){g.players.forEach(p=>{const grossFlow=Math.round(p.cash-p.quarterStartCash+p.quarterCapex),taxable=Math.max(0,grossFlow),tax=Math.round(taxable*TAX_RATE);p.cash-=tax;p.taxPaid=(p.taxPaid||0)+tax;p.taxHistory??=[];p.taxHistory.push({round:g.round,grossFlow,taxable,tax});p.quarterStartCash=p.cash;p.quarterCapex=0;if(tax)addLog('TAX OFFICE',`${p.name} settled A$${tax}m tax on A$${taxable}m positive quarterly cashflow.`)});}
