let difficulty='easy',mode='solo',g=null,audioOn=true,musicOn=false,voiceOn=false,audioCtx=null,musicTimer=null,musicStep=0,toastTimer,onlineSession=null,roomPoll=null,latestRoomUpdate=0,marketQuote=null,spokenTurn='';
const TAX_RATE=.25;
function makeGame(){const names=mode==='pass'?['You','South Australia']:mode==='online'?[onlineSession?.name||'Treasurer',onlineSession?.players?.[1]||'Guest']:['You','New Zealand','Singapore','European Union'];g={players:names.map((name,i)=>({name,cash:100,pos:0,color:colors[i],inventory:{Fuel:1,Food:1,Tech:0,Medicine:0},owned:[],policy:'balanced',human:mode==='pass'||mode==='online'||i===0,tradeUsed:false,policyUsed:false,alive:true,taxPaid:0,taxHistory:[],quarterStartCash:100,quarterCapex:0})),round:1,turn:0,market:{...markets},weather:weather[Math.floor(Math.random()*weather.length)],events:0,done:false,lastRoll:[1,1],resilience:58};if(difficulty==='hard'&&mode==='solo'){g.players.slice(1).forEach(p=>{p.cash=115;p.quarterStartCash=115})}if(mode==='online'){g.players.forEach(p=>p.human=true)}return g}
function coords(i){if(i<6)return[1,i+1];if(i<11)return[i-4,6];if(i<16)return[6,11-i];return[20-i,1]}
function start(){if(mode==='online'&&!onlineSession){toast('Create or join an online room first.');return}g=makeGame();$('#welcome').classList.add('hidden');$('#game').classList.remove('hidden');document.body.classList.add('weather-clear');render();addLog('SYSTEM',mode==='online'?`Online room ${onlineSession.code} opened. Share the code with one opponent.`:'Trade desk open. Game prices are simulated; quote benchmark loads separately.');if(mode==='online'){publishRoomState();startRoomPolling()}loadQuote();toast(mode==='online'?`Room ${onlineSession.code} is ready.`:'Briefing loaded — good luck, Treasurer.');}
function render(){if(!g)return;$('#quarter-label').textContent=`QUARTER ${String(g.round).padStart(2,'0')} OF 12`;$('#header-date').textContent=`FY ${2025+Math.ceil(g.round/4)}–${String(2026+Math.ceil(g.round/4)).slice(-2)}`;$('#weather-line').innerHTML=`◌ &nbsp; NATIONAL OUTLOOK: ${g.weather}`;const isLocalTurn=g.players[g.turn].human&&(mode!=='online'||g.turn===onlineSession?.index);$('#turn-indicator').textContent=isLocalTurn?'YOUR TURN':`${g.players[g.turn].name.toUpperCase()} MOVING`;$('#turn-indicator').classList.toggle('ai',!isLocalTurn);$('#turn-title').textContent=isLocalTurn?'The floor is yours.':`${g.players[g.turn].name} is trading.`;$('#turn-message').textContent=isLocalTurn?'Trade goods, set a policy, then roll to move your portfolio around the country.':mode==='online'?'Waiting for your opponent to finish their turn.':'The market never waits. Watch their moves and plan your next quarter.';$('#roll-btn').disabled=!isLocalTurn||g.done;$('#trade-btn').disabled=!isLocalTurn||g.players[g.turn].tradeUsed;$('#policy-btn').disabled=!isLocalTurn||g.players[g.turn].policyUsed;drawBoard();drawPlayers();drawMarket();drawResilience();weatherEffect();$('#connection-status').textContent=onlineSession?`· ROOM ${onlineSession.code}`:'';$('#tax-ledger-btn').onclick=openLedger;const turnKey=`${g.round}:${g.turn}`;if(voiceOn&&isLocalTurn&&spokenTurn!==turnKey){spokenTurn=turnKey;speak(`Quarter ${g.round}. Your turn, ${g.players[g.turn].name}.`)} }
function drawBoard(){const board=$('#board');board.innerHTML='';tiles.forEach((t,i)=>{const [r,c]=coords(i);const e=document.createElement('div');e.className=`tile ${t.type} ${g.players.some(p=>p.pos===i)?'current-tile':''}`;e.style.gridRow=r;e.style.gridColumn=c;e.innerHTML=`<span class="tile-icon">${t.icon}</span><div><div class="tile-name">${t.name}</div><div class="tile-type">${t.kind}</div></div><span class="tile-meta">${t.detail}</span>`;let owner=g.players.find(p=>p.owned.includes(i));if(owner){const o=document.createElement('i');o.className='tile-owner';o.style.background=owner.color;e.append(o)}const pawns=document.createElement('div');pawns.className='tile-pawns';g.players.filter(p=>p.pos===i).forEach(p=>{const pawn=document.createElement('i');pawn.className='pawn';pawn.style.setProperty('--pawn',p.color);pawn.title=p.name;pawns.append(pawn)});e.append(pawns);board.append(e)});const center=document.createElement('div');center.className='cell-center';center.innerHTML=`<div class="australia-mark">✳</div><div class="center-kicker">AUSTRALIA / 2026</div><div class="center-title">The long game.</div><div class="center-copy">Trade, resilience &amp; a changing world</div><div class="center-quarter">QUARTER ${String(g.round).padStart(2,'0')} &nbsp;·&nbsp; ${g.weather}</div>`;board.append(center)}
