async function joinRoom(){const code=$('#room-code').value.trim().toUpperCase();if(!code){toast('Enter a room code first.');return}try{const data=await api(`/api/rooms/${code}/join`,{method:'POST',body:JSON.stringify({name:$('#player-name').value.trim()||'Guest'})});onlineSession={code:data.code,index:1,name:data.players[1],players:data.players};$('#room-help').textContent=`Joined ${data.code}. Waiting for the room host to open the game…`;$('#join-room').disabled=true;const wait=async()=>{try{const room=await api(`/api/rooms/${code}`);onlineSession.players=room.players;if(room.state){normalizeOnlineState(room.state,room.players,room.stateUpdatedAt);startRoomPolling();loadQuote();return}setTimeout(wait,1000)}catch(error){$('#room-help').textContent=error.message;$('#join-room').disabled=false}};wait()}catch(error){toast(error.message)}}
function modal(title,kicker,content){const root=$('#modal-root');root.innerHTML=`<div class="modal"><div class="modal-head"><div><span class="section-kicker">${kicker}</span><h2>${title}</h2></div><button class="modal-close" aria-label="Close">×</button></div>${content}</div>`;root.classList.remove('hidden');$('.modal-close',root).onclick=()=>root.classList.add('hidden');root.onclick=e=>{if(e.target===root)root.classList.add('hidden')}}
