function openLedger(){if(!g)return;const p=g.players[onlineSession?.index||0],history=p.taxHistory||[],totalTax=history.reduce((sum,row)=>sum+row.tax,0),totalTaxable=history.reduce((sum,row)=>sum+row.taxable,0),rows=history.length?history.slice().reverse().map(row=>`<div class="ledger-row"><span>QUARTER ${String(row.round).padStart(2,'0')}<small>Cashflow A$${row.grossFlow}m · taxable A$${row.taxable}m</small></span><b class="${row.tax?'negative':''}">−A$${row.tax}m</b></div>`).join(''):'<p class="modal-copy">Quarterly settlements will appear here as you play.</p>';modal('Tax & cashflow ledger','SIMPLIFIED GAME RULES',`<p class="modal-copy">This is a fictional game ledger, not tax advice or a model of Australian tax law. The game applies a flat 25% to positive quarterly cashflow; asset and local-production investments are added back before calculating taxable flow.</p><div class="tax-summary"><div class="tax-stat"><span>SETTLED TAX</span><b>A$${totalTax}m</b></div><div class="tax-stat"><span>TAXABLE FLOW</span><b>A$${totalTaxable}m</b></div><div class="tax-stat"><span>RATE</span><b>25%</b></div></div><div class="ledger-list">${rows}</div><div class="modal-foot"><span>PLAYER · ${esc(p.name)}</span><b>CASH A$${Math.round(p.cash)}m</b></div>`)}
