86:     const room = rooms.get(roomPath[1].toUpperCase());
87:     if (!room) return send(res, 404, { error:'Room not found. It may have expired after a server restart.' });
88:     if (req.method === 'GET') return send(res, 200, roomView(room));
89:     if (req.method === 'PUT') {
