+  let timeout;
+  try {
+    const controller = new AbortController();
+    timeout = setTimeout(() => controller.abort(), 6500);
+    const url = 'https://query1.finance.yahoo.com/v8/finance/chart/TIO%3DF?range=1d&interval=5m';
